const base = $('입력 데이터 정리').first().json;

const rawTranscript =
  $json.text ??
  $json.transcript ??
  $json.data?.text ??
  null;

const transcript =
  typeof rawTranscript === 'string' &&
  rawTranscript.trim() !== ''
    ? rawTranscript.trim()
    : null;

return [
  {
    json: {
      ...base,
      consultation_text: transcript
    }
  }
];

const input = $input.first().json;

const rawText =
  input.consultation_text ??
  input.consultation_result?.consultation_text ??
  null;

const consultationText =
  typeof rawText === 'string' &&
  rawText.trim() !== ''
    ? rawText.trim()
    : null;

return [
  {
    json: {
      ...input,
      consultation_text: consultationText
    }
  }
];

const input = $input.first().json;
const result = input.consultation_result ?? {};


// YYYY-MM-DD 날짜 검증
function normalizeDate(value) {
  if (value == null || value === '') {
    return null;
  }

  const date = String(value).trim();

  // 형식 검사
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    return null;
  }

  // 실제 존재하는 날짜인지 검사
  const [year, month, day] = date.split('-').map(Number);
  const parsed = new Date(Date.UTC(year, month - 1, day));

  if (
    parsed.getUTCFullYear() !== year ||
    parsed.getUTCMonth() !== month - 1 ||
    parsed.getUTCDate() !== day
  ) {
    return null;
  }

  return date;
}


// Boolean 정리
function normalizeBoolean(value) {
  if (typeof value === 'boolean') {
    return value;
  }

  if (value === 'true') {
    return true;
  }

  if (value === 'false') {
    return false;
  }

  return null;
}


return [
  {
    json: {
      customer_id: input.customer_id ?? null,
      consultation_id: input.consultation_id ?? null,
      staff_id: input.staff_id ?? null,
      store_id: input.store_id ?? null,

      recording_url:
        input.recording_url &&
        String(input.recording_url).trim() !== ''
          ? String(input.recording_url).trim()
          : null,

      consultation_result: {
        consultation_text:
          result.consultation_text ?? '',

        customer_response:
          result.customer_response ?? null,

        selected_device_id:
          result.selected_device_id ?? null,

        selected_plan_id:
          result.selected_plan_id ?? null,

        follow_up_requested:
          normalizeBoolean(result.follow_up_requested),

        preferred_follow_up_date:
          normalizeDate(result.preferred_follow_up_date)
      }
    }
  }
];

const saved = $input.first().json;

return [
  {
    json: {
      success: true,
      feature_id: 'F-04',

      customer_id: saved.customer_id ?? null,
      consultation_id: saved.consultation_id ?? null,

      summary: saved.summary ?? null,
      result_status: saved.result_status ?? null,

      customer_response: saved.customer_response ?? null,
      interested_product: saved.interested_product ?? null,
      interested_plan: saved.interested_plan ?? null,
      special_notes: saved.special_notes ?? null,

      follow_up_required: saved.follow_up_required ?? false,
      follow_up_reason: saved.follow_up_reason ?? null,

      preferred_follow_up_date:
        saved.preferred_follow_up_date ?? null
    }
  }
];

const input = $('입력 데이터 정리').first().json;

return [
  {
    json: {
      success: false,
      feature_id: 'F-04',

      error_code: 'EMPTY_CONSULTATION',
      message: '처리할 상담 내용이 없습니다.',

      customer_id: input.customer_id ?? null,
      consultation_id: input.consultation_id ?? null
    }
  }
];
